import{_ as e,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"{% macro %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Вызов макросов","slug":"вызов-макросов","link":"#вызов-макросов","children":[]},{"level":2,"title":"Вложенные макросы","slug":"вложенные-макросы","link":"#вложенные-макросы","children":[]},{"level":2,"title":"Контекстная переменная","slug":"контекстная-переменная","link":"#контекстная-переменная","children":[]}],"relativePath":"3.x/ru/markup/tag/macro.md","filePath":"3.x/ru/markup/tag/macro.md"}'),u={name:"3.x/ru/markup/tag/macro.md"};function k(r,n,g,m,d,w){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"{% macro %}",-1)),s(p),n[1]||(n[1]=i(`<p>Тег <code>{% macro %}</code> позволяет определять пользовательские функции в шаблонах, аналогично обычным языкам программирования.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> input<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    ...
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Также можно указать имя макроса после закрывающего тега для лучшей читаемости:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> input<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    ...
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> input <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Следующий пример определяет функцию <code>input()</code>, принимающую 4 аргумента. Связанные значения доступны как переменные внутри разметки.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> input<span class="token punctuation">(</span>name<span class="token punctuation">,</span> value<span class="token punctuation">,</span> type<span class="token punctuation">,</span> size<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
        <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type<span class="token operator">|</span>default<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>text<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> value<span class="token operator">|</span>e <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">size</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> size<span class="token operator">|</span>default<span class="token punctuation">(</span><span class="token number">20</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Аргументы макросов не определяют значения по умолчанию и всегда считаются необязательными.</p></blockquote><h2 id="вызов-макросов"><a href="#вызов-макросов" class="header-anchor">#</a> Вызов макросов</h2><p>Перед использованием макроса его необходимо «импортировать» с помощью тега <code>{% import %}</code>. Если макрос определён в том же шаблоне, можно использовать специальную переменную <code>_self</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as form <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Здесь функции макроса назначены переменной <code>form</code> и доступны для вызова как любая другая функция.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form<span class="token punctuation">.</span>input<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>username<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form<span class="token punctuation">.</span>input<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>password<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token boolean">null</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>password<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Макросы можно определять в <a href="./../../cms/themes/partials.html">фрагменте темы</a> и импортировать по имени. Чтобы импортировать макросы из фрагмента с именем <strong>macros/form.htm</strong>, просто передайте имя после тега <code>import</code> в кавычках как строку.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> <span class="token string"><span class="token punctuation">&#39;</span>macros/form<span class="token punctuation">&#39;</span></span> as form <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Также можно импортировать макросы из <a href="./../../extend/services/response-view.html">системного файла представления</a> — они также будут приняты. Чтобы импортировать из <strong>plugins/acme/blog/views/macros.htm</strong>, просто передайте подсказку пути.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> <span class="token string"><span class="token punctuation">&#39;</span>acme.blog::macros<span class="token punctuation">&#39;</span></span> as form <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="вложенные-макросы"><a href="#вложенные-макросы" class="header-anchor">#</a> Вложенные макросы</h2><p>Если вы хотите использовать макрос внутри другого макроса из того же шаблона, необходимо импортировать его локально.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> input<span class="token punctuation">(</span>name<span class="token punctuation">,</span> value<span class="token punctuation">,</span> type<span class="token punctuation">,</span> size<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
        <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type<span class="token operator">|</span>default<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>text<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> value<span class="token operator">|</span>e <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">size</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> size<span class="token operator">|</span>default<span class="token punctuation">(</span><span class="token number">20</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> wrapped_input<span class="token punctuation">(</span>name<span class="token punctuation">,</span> value<span class="token punctuation">,</span> type<span class="token punctuation">,</span> size<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as form <span class="token delimiter punctuation">%}</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>field<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form<span class="token punctuation">.</span>input<span class="token punctuation">(</span>name<span class="token punctuation">,</span> value<span class="token punctuation">,</span> type<span class="token punctuation">,</span> size<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="контекстная-переменная"><a href="#контекстная-переменная" class="header-anchor">#</a> Контекстная переменная</h2><p>Макросы не имеют доступа к переменным текущей страницы.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- October CMS --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site_name <span class="token delimiter punctuation">}}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> myFunction<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- NULL --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site_name <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы можете передать переменные в функцию, используя специальную переменную <code>_context</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> myFunction<span class="token punctuation">(</span>vars<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> vars<span class="token punctuation">.</span>site_name <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as form <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- October CMS --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form<span class="token punctuation">.</span>myFunction<span class="token punctuation">(</span>_context<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div>`,24))])}const _=e(u,[["render",k]]);export{f as __pageData,_ as default};
